import json
import re

class JsonExtractor:
    def extract(self, raw_text: str) -> dict:
        decoder = json.JSONDecoder()
        for match in re.finditer(r"\{", raw_text):
            try:
                obj, _ = decoder.raw_decode(raw_text, match.start())
            except json.JSONDecodeError:
                continue
            if isinstance(obj, dict):
                return obj
        raise ValueError("No JSON object found")

    def validate(self, data: dict, required_keys: list) -> bool:
        return all(key in data for key in required_keys)

    def extract_and_validate(self, raw_text: str, required_keys: list) -> dict:
        data = self.extract(raw_text)
        if not self.validate(data, required_keys):
            missing = [k for k in required_keys if k not in data]
            raise ValueError(f"Missing required keys: {missing}")
        return data

# Test it:
extractor = JsonExtractor()

raw1 = 'Sure! Here is the result: {"sentiment": "positive", "confidence": 0.95} Hope that helps!'
result1 = extractor.extract(raw1)
print(result1["sentiment"])
print(extractor.validate(result1, ["sentiment", "confidence"]))

raw2 = 'No json here at all'
try:
    extractor.extract(raw2)
except ValueError:
    print("No JSON found")

raw3 = '{"tool": "search", "args": {"query": "weather"}}'
result3 = extractor.extract_and_validate(raw3, ["tool", "args"])
print(result3["tool"])

class ToolRouter:
    def __init__(self, tools: dict):
        self.tools = dict(tools)

    def route(self, user_message: str) -> dict:
        text = str(user_message).lower()
        for name in self.tools:
            if str(name).lower() in text:
                return {"tool": name, "args": {"input": user_message}}
        return {"tool": "none", "args": {}}

    def is_valid_call(self, call: dict) -> bool:
        return (
            isinstance(call, dict)
            and "tool" in call
            and "args" in call
            and isinstance(call["args"], dict)
        )


# Test it:
router = ToolRouter({
    "calculator": "Do math",
    "search": "Search the web",
    "weather": "Get weather info"
})

c1 = router.route("Can you use the calculator for 5+3?")
print(c1["tool"])

c2 = router.route("Hello there!")
print(c2["tool"])

print(router.is_valid_call(c1))
print(router.is_valid_call({"missing": "keys"}))
